	OrgName      string
	InputPath    string
	DryRun       bool
	IncludeList  []string
	SkipEntities bool
}

// ImportResultOptions configures import result rendering.
type ImportResultOptions struct {
	Format            Format
	MaxErrors         int
	Verbose           bool
